  1→import React from 'react';
  2→import { ParshaLocation } from '../../utils/navigationUtils';
  3→import './Header.css';
  4→
  5→interface HeaderProps {
  6→  currentAmud: number;
  7→  totalAmudim: number;
  8→  showNikud: boolean;
  9→  wordGap: number;
 10→  currentParsha?: ParshaLocation;
 11→  onNavigateAmud: (direction: 'next' | 'prev') => void;
 12→  onToggleNikud: () => void;
 13→  onAdjustWordGap: (change: number) => void;
 14→}
 15→
 16→export const Header: React.FC<HeaderProps> = ({
 17→  currentAmud,
 18→  totalAmudim,
 19→  showNikud,
 20→  wordGap,
 21→  currentParsha,
 22→  onNavigateAmud,
 23→  onToggleNikud,
 24→  onAdjustWordGap
 25→}) => {
 26→  return (
 27→    <div className="header">
 28→      <div className="header-content">
 29→        <div className="title-section">
 30→          <strong>תִּקּוּן קוֹרִאים</strong>
 31→          {currentParsha && (
 32→            <div className="parsha-info">
 33→              <span className="sefer">{currentParsha.sefer}</span>
 34→              <span className="separator">•</span>
 35→              <span className="parsha">{currentParsha.parsha}</span>
 36→              {currentParsha.aliya && (
 37→                <>
 38→                  <span className="separator">•</span>
 39→                  <span className="aliya">עליה {currentParsha.aliya}</span>
 40→                </>
 41→              )}
 42→            </div>
 43→          )}
 44→        </div>
 45→        
 46→        <div className="navigation-hints">
 47→          <div className="keyboard-hints">
 48→            <span>← → עמוד</span>
 49→            <span>↑ ↓ פרשה</span>
 50→            <span>N נקוד</span>
 51→          </div>
 52→          {currentParsha && (
 53→            <div className="navigation-status">
 54→              <span className="status-indicator">🔗</span>
 55→              <span>ניווט פעיל</span>
 56→            </div>
 57→          )}
 58→        </div>
 59→        
 60→        <div className="amud-info">
 61→          עמוד {currentAmud} מתוך {totalAmudim}
 62→        </div>
 63→        {/* <div className="navigation">
 64→          <button 
 65→            onClick={() => onNavigateAmud('prev')}
 66→            disabled={currentAmud <= 1}
 67→            className="nav-button"
 68→          >
 69→            &lt;&lt;
 70→          </button>
 71→          <span className="amud-info">
 72→            Amud {currentAmud} of {totalAmudim}
 73→          </span>
 74→          <button 
 75→            onClick={() => onNavigateAmud('next')}
 76→            disabled={currentAmud >= totalAmudim}
 77→            className="nav-button"
 78→          >
 79→            &gt;&gt;
 80→          </button>
 81→        </div> */}
 82→        <div className="controls">
 83→          <button onClick={onToggleNikud} className="control-button">
 84→            Nikud {showNikud ? 'ON' : 'OFF'}
 85→          </button>
 86→          {!showNikud && (
 87→            <div className="word-gap-controls">
 88→              <button 
 89→                onClick={() => onAdjustWordGap(-0.5)}
 90→                disabled={wordGap <= 1}
 91→                className="gap-button"
 92→              >
 93→                [-]
 94→              </button>
 95→              <span className="gap-display">[max gap: {wordGap}]</span>
 96→              <button 
 97→                onClick={() => onAdjustWordGap(0.5)}
 98→                disabled={wordGap >= 6}
 99→                className="gap-button"
100→              >
101→                [+]
102→              </button>
103→            </div>
104→          )}
105→        </div>
106→      </div>
107→    </div>
108→  );
109→};
