.text-line.satum,
.text-line[class*="satum"] {
  text-align: left; /* Override default for satum */
  display: flex;
  justify-content: space-between;
  width: 100%;
}

.text-line.satum .text-fragment,
.text-line[class*="satum"] .text-fragment {
  display: inline-block; /* Make fragments flexible for justify-between */
}

.text-line.patuch {
  text-align: right;
}

/* Aliyah markers */
.aliyah-markers {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  pointer-events: none;
}

.aliyah-marker {
  width: 8px;
  height: 8px;
  background-color: #007acc;
  border-radius: 50%;
  margin: 1px 0;
}

/* Right-side verse index like in reference (red alef-bet) */
.verse-index {
  position: absolute;
  right: 0;
  top: 0;
  color: #c00;
  font-weight: 600;
  padding-left: 8px;
  transform: translateY(5%);
}

/* Legacy line labels (pasuk on right, aliyah on left) */
.labelright {
  position: absolute;
  right: -20px;
  top: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  pointer-events: none;
}

.labelright .pasuk {
  color: #c00;
  font-weight: 600;
  font-size: 14px;
  line-height: 1;
}

.labelleft {
  position: absolute;
  left: -20px;
  top: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  pointer-events: none;
}

.labelleft .aliya {
  color: #007acc;
  font-weight: 600;
  font-size: 14px;
  line-height: 1;
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .text-line {
  font-size: 20px;
  padding: 0 4px;
  }
}

@media (max-width: 480px) {
  .text-line {
  font-size: 18px;
  line-height: 1.8;
  }
}
