        <div className="controls">
          <button onClick={onToggleNikud} className="control-button">
            Nikud {showNikud ? 'ON' : 'OFF'}
          </button>
          {!showNikud && (
            <div className="word-gap-controls">
              <button 
                onClick={() => onAdjustWordGap(-0.5)}
