              </button>
              <span className="gap-display">[max gap: {wordGap}]</span>
              <button 
                onClick={() => onAdjustWordGap(0.5)}
                disabled={wordGap >= 6}
                className="gap-button"
              >
                [+]
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

