/* ── Navigation hints ───────────────────────────────── */
.navigation-hints {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.keyboard-hints {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 0.72rem;
  color: var(--color-text-secondary);
  padding: 4px 10px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background: var(--color-bg);
}

.keyboard-hints span {
  white-space: nowrap;
}

.navigation-status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.72rem;
  color: var(--color-success);
  padding: 3px 8px;
  border-radius: var(--radius-md);
  background: rgba(5, 150, 105, 0.08);
}

/* Green dot replaces the link emoji */
.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-success);
  flex-shrink: 0;
}

/* ── Amud info ──────────────────────────────────────── */
.amud-info {
  color: var(--color-text-secondary);
  font-size: 0.85rem;
  font-weight: 500;
}

/* ── Controls ───────────────────────────────────────── */
.controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.control-button {
  background: var(--color-accent);
  color: #fff;
  border: none;
  padding: 6px 14px;
  cursor: pointer;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 13px;
  transition: background var(--transition);
}

.control-button:hover {
  background: var(--color-accent-hover);
}

.control-button:active {
  opacity: 0.9;
}

/* Language toggle pill */
.lang-toggle {
  background: var(--color-bg);
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
  min-width: 38px;
  text-align: center;
}

.lang-toggle:hover {
  background: var(--color-accent-light);
}

/* ── Word gap controls ──────────────────────────────── */
.word-gap-controls {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 8px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background: var(--color-bg);
}

.gap-button {
  background: var(--color-accent);
  color: #fff;
  border: none;
  padding: 4px 10px;
  cursor: pointer;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 700;
  transition: background var(--transition);
  min-width: 28px;
  text-align: center;
}

.gap-button:hover:not(:disabled) {
  background: var(--color-accent-hover);
}

.gap-button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.gap-display {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  min-width: 40px;
  text-align: center;
}

/* ── Mobile ─────────────────────────────────────────── */
@media (max-width: 768px) {
  .header {
    padding: 10px 16px;
  }

  .header-content {
    flex-direction: column;
    gap: 8px;
    align-items: center;
  }

  .title-section > strong {
    font-size: 1.2rem;
  }

  .controls {
    flex-wrap: wrap;
    justify-content: center;
    gap: 6px;
  }

  .control-button {
    padding: 5px 10px;
    font-size: 12px;
  }

  .word-gap-controls {
    padding: 3px 6px;
    gap: 6px;
  }

  .gap-button {
    padding: 3px 8px;
    font-size: 13px;
    min-width: 26px;
  }

  .keyboard-hints {
    display: none;
  }
}

