.footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  margin-top: 60px;
  padding: 24px 0;
}

.footer-content {
  max-width: 1000px;
  margin: 0 auto;
  padding: 0 24px;
  text-align: center;
}

.footer-info {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 15px;
  color: var(--color-text);
  font-weight: 600;
}

.footer-info > span {
  color: var(--color-accent);
  font-size: 16px;
  font-weight: 700;
}

.help-button {
  background: var(--color-accent);
  color: #fff;
  border: none;
  padding: 8px 18px;
  cursor: pointer;
  border-radius: var(--radius-md);
  font-size: 13px;
  font-weight: 600;
  transition: background var(--transition);
}

.help-button:hover {
  background: var(--color-accent-hover);
}

.help-panel {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  margin-top: 16px;
  animation: fadeIn 0.2s ease-out;
}

.help-panel h4 {
  margin: 0 0 12px 0;
  font-size: 15px;
  color: var(--color-accent);
  font-weight: 700;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 6px;
}

.help-panel ul {
  margin: 10px 0;
  padding-inline-start: 20px;
  list-style-type: disc;
}

.help-panel li {
  margin: 6px 0;
  font-size: 14px;
  color: var(--color-text-secondary);
}

.help-panel li::marker {
  color: var(--color-accent);
}

.help-panel kbd {
  background: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  padding: 2px 6px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', monospace;
  font-size: 12px;
  font-weight: 600;
  margin: 0 2px;
  display: inline-block;
}

@media (max-width: 768px) {
  .footer {
    padding: 20px 0;
  }

  .footer-content {
    padding: 0 16px;
  }

  .footer-info {
    flex-direction: column;
    gap: 10px;
  }

  .help-button {
    padding: 6px 14px;
    font-size: 12px;
  }

  .help-panel li {
    font-size: 13px;
  }
}

