/* ── Toggle button ───────────────────────────────────── */
.parsha-nav-toggle {
  position: fixed;
  top: 16px;
  inset-inline-start: 16px;
  z-index: 1100;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  width: 42px;
  height: 42px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  box-shadow: var(--shadow-md);
  transition: background var(--transition);
}

.parsha-nav-toggle:hover {
  background: var(--color-bg);
}

.parsha-nav-toggle.active {
  background: var(--color-accent);
}

.hamburger-line {
  width: 18px;
  height: 2px;
  background: var(--color-accent);
  border-radius: 1px;
  transition: transform 0.25s ease, opacity 0.25s ease;
  transform-origin: center;
}

.parsha-nav-toggle.active .hamburger-line {
  background: #fff;
}

.parsha-nav-toggle.active .hamburger-line:nth-child(1) {
  transform: rotate(45deg) translate(3px, 3px);
}

.parsha-nav-toggle.active .hamburger-line:nth-child(2) {
  opacity: 0;
}

.parsha-nav-toggle.active .hamburger-line:nth-child(3) {
  transform: rotate(-45deg) translate(3px, -3px);
}

/* ── Backdrop ────────────────────────────────────────── */
.parsha-nav-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.3);
  z-index: 1050;
  animation: fadeIn 0.2s ease-out;
}

/* ── Panel ───────────────────────────────────────────── */
.parsha-navigation {
  position: fixed;
  top: 0;
  inset-inline-start: 0;
  width: 380px;
  height: 100vh;
  background: var(--color-surface);
  box-shadow: 4px 0 16px rgba(0, 0, 0, 0.08);
  z-index: 1100;
  transform: translateX(-100%);
  transition: transform 0.3s ease;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

[dir="rtl"] .parsha-navigation {
  transform: translateX(100%);
}

.parsha-navigation.open {
  transform: translateX(0);
}

/* ── Nav header ──────────────────────────────────────── */
.parsha-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px;
  border-bottom: 1px solid var(--color-border);
}

.parsha-nav-header h2 {
  margin: 0;
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--color-accent);
}

.close-button {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  width: 32px;
  height: 32px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: var(--color-text-secondary);
  transition: background var(--transition);
}

.close-button:hover {
  background: var(--color-border);
}

/* ── Scrollable content ──────────────────────────────── */
.parsha-nav-content {
  flex: 1;
  padding: 20px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--color-border) transparent;
}

.parsha-nav-content::-webkit-scrollbar {
  width: 5px;
}

.parsha-nav-content::-webkit-scrollbar-track {
  background: transparent;
}

.parsha-nav-content::-webkit-scrollbar-thumb {
  background: var(--color-border);
  border-radius: 3px;
}

/* ── Search ──────────────────────────────────────────── */
.search-container {
  margin-bottom: 20px;
}

.search-input {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  font-family: inherit;
  background: var(--color-bg);
  transition: border-color var(--transition);
}

.search-input:focus {
  outline: none;
  border-color: var(--color-accent);
}

.search-input::placeholder {
  color: var(--color-text-secondary);
}

/* ── Current selection ───────────────────────────────── */
.current-selection {
  background: var(--color-accent-light);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 14px;
  margin-bottom: 20px;
}

.current-label {
  display: block;
  font-size: 0.8rem;
  color: var(--color-text-secondary);
  margin-bottom: 6px;
  font-weight: 500;
}

.current-path {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.current-sefer,
.current-parsha,
.current-aliya {
  padding: 3px 8px;
  background: var(--color-surface);
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--color-accent);
}

.separator {
  color: var(--color-text-secondary);
  font-weight: bold;
}

/* ── Section headings ────────────────────────────────── */
.nav-section {
  margin-bottom: 24px;
}

.nav-section h3 {
  margin: 0 0 12px 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-accent);
  padding-bottom: 6px;
  border-bottom: 1px solid var(--color-border);
}

/* ── Seforim grid ────────────────────────────────────── */
.seforim-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}

.sefer-button {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
  text-align: inherit;
}

.sefer-button:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.sefer-button.selected {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.sefer-button.current {
  border-color: var(--color-accent);
  box-shadow: inset 3px 0 0 var(--color-accent);
}

[dir="ltr"] .sefer-button.current {
  box-shadow: inset -3px 0 0 var(--color-accent);
}

.sefer-name {
  display: block;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 2px;
}

.sefer-count {
  display: block;
  font-size: 0.8rem;
  color: var(--color-text-secondary);
}

/* ── Parshios grid ───────────────────────────────────── */
.parshios-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 8px;
}

.parsha-button {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
  text-align: inherit;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 44px;
}

.parsha-button:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.parsha-button.selected {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.parsha-button.current {
  border-color: var(--color-accent);
  box-shadow: inset 3px 0 0 var(--color-accent);
}

[dir="ltr"] .parsha-button.current {
  box-shadow: inset -3px 0 0 var(--color-accent);
}

.parsha-name {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-text);
  flex: 1;
}

/* CSS circle replaces the blue diamond emoji */
.aliya-indicator {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-accent);
  flex-shrink: 0;
  margin-inline-start: 6px;
}

/* ── Aliyos grid ─────────────────────────────────────── */
.aliyos-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 6px;
}

.aliya-button {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 10px 14px;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
  text-align: inherit;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.aliya-button:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.aliya-button.current {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.aliya-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text);
}

.aliya-range {
  font-size: 0.8rem;
  color: var(--color-text-secondary);
  font-family: monospace;
  direction: ltr;
}

/* ── Quick actions ───────────────────────────────────── */
.quick-actions-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.quick-action-button {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 10px;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
  text-align: center;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-accent);
}

.quick-action-button:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

/* ── Responsive ──────────────────────────────────────── */
@media (max-width: 768px) {
  .parsha-navigation {
    width: 100vw;
    max-width: 340px;
  }

  .parshios-grid {
    grid-template-columns: 1fr;
  }

  .quick-actions-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .parsha-nav-content {
    padding: 14px;
  }

  .parsha-nav-header {
    padding: 14px;
  }

  .parsha-nav-header h2 {
    font-size: 1.15rem;
  }
}

