file.content:
.toast {
  position: fixed;
  top: 100px;
  right: 24px;
  max-width: 320px;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius: 12px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.3);
  z-index: 10000;
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  direction: rtl;
  text-align: right;
}

.toast-show {
  transform: translateX(0);
}

.toast-content {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
}

.toast-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-weight: bold;
  font-size: 14px;
}

.toast-message {
  flex: 1;
  font-size: 14px;
  font-weight: 500;
  color: #333;
}

.toast-info .toast-icon {
  background: #e3f2fd;
  color: #1976d2;
}

.toast-success .toast-icon {
  background: #e8f5e8;
  color: #2e7d32;
}

.toast-warning .toast-icon {
  background: #fff3e0;
  color: #f57c00;
}

.toast-error .toast-icon {
  background: #ffebee;
  color: #d32f2f;
}

@media (max-width: 480px) {
  .toast {
    right: 12px;
    left: 12px;
    max-width: none;
  }
}

